local M = {}

---@param command string
---@param root string?
---@return string?
local function executable(command, root)
    if root then
        local path = vim.fs.joinpath(root, "node_modules", ".bin", command)
        if vim.fn.executable(path) == 1 then
            return path
        end
    end

    if vim.fn.executable(command) == 1 then
        return command
    end
end

---@param command string
---@param arguments string[]? Default `{ "--stdio" }`.
---@return fun(
---  dispatchers: vim.lsp.rpc.Dispatchers,
---  config: vim.lsp.ClientConfig,
---):vim.lsp.rpc.PublicClient
function M.cmd(command, arguments)
    return function(dispatchers, config)
        local argv0 = executable(command, config.root_dir)
        if not argv0 then
            error(
                ("`%s` is not availabe. The corresponding language server will not be started."):format(
                    command
                ),
                0 -- No location prefix.
            )
        end

        return vim.lsp.rpc.start(
            { argv0, unpack(arguments or { "--stdio" }) },
            dispatchers
        )
    end
end

return M
